import json,os
wf=json.load(open("/root/direct-sync/maersk_ref/wf_crm.json"))
vals={}
for n in wf["nodes"]:
    p=n.get("parameters") or {}
    for grp in ("headerParameters","bodyParameters"):
        for it in (p.get(grp) or {}).get("parameters",[]):
            nm,v=it.get("name"),str(it.get("value",""))
            if nm in ("Consumer-Key","client_id","client_secret") and v and "{{" not in v:
                vals.setdefault({"Consumer-Key":"MAERSK_CONSUMER_KEY","client_id":"MAERSK_CLIENT_ID","client_secret":"MAERSK_CLIENT_SECRET"}[nm],v)
os.makedirs("/root/direct-sync/secure",exist_ok=True); os.chmod("/root/direct-sync/secure",0o700)
p="/root/direct-sync/secure/maersk.env"
with open(p,"w") as f:
    for k,v in vals.items(): f.write("%s=%s\n"%(k,v))
os.chmod(p,0o600)
print("SECRETS_SAVED:", ", ".join("%s(len=%d)"%(k,len(v)) for k,v in vals.items()))
print("FILE:", p, oct(os.stat(p).st_mode)[-3:])
EOF
echo "== Відбір Maersk =="; cat "/root/direct-sync/maersk_ref/Відбір_Maersk.js"
